package dev.zomboid.gore;
import java.util.*;import dev.zomboid.firstaid.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.ServerPlayer;import de.maxhenkel.corpse.entities.CorpseEntity;import com.raiiiden.ragdollified.server.ServerRagdollSyncManager;
public class Test45 {
 static int count;static void ok(boolean b,String s){count++;if(!b)throw new AssertionError(s);}
 public static class State {public Object[] wounds=new Object[8];}
 public static class Model {public void scheduleResync(){}}
 public static class Packet {public int[]goreCuts24;public int goreState12;public String medical45;}
 public static class Spawner {public boolean addFreshEntity(Object corpse){return true;}}
 public static void main(String[]args)throws Exception{
  Random random=new Random(45);for(int i=0;i<1000;i++){double x=random.nextDouble(),y=random.nextDouble()*1.8,z=random.nextDouble(),yaw=random.nextDouble()*Math.PI*2;for(boolean prone:new boolean[]{false,true})for(boolean crouch:new boolean[]{false,true}){double[]p=Coordinates45.toWorld(x,y,z,yaw,prone,crouch),q=Coordinates45.toLocal(p[0],p[1],p[2],yaw,prone,crouch);ok(Math.abs(x-q[0])+Math.abs(y-q[1])+Math.abs(z-q[2])<1e-8,"posture/yaw inverse matches forward transform");}}
  Object w=R.make("ichttt.mods.firstaid.survival.ClinicalState$Wound");int[] a=Wounds45.add(new int[0],.9,.1,0,1);R.set(w,"marks45",a);R.set(w,"healingLeft",2400);R.set(w,"markHealingStart45",2400);Wounds45.tick(w);ok(((int[])R.get(w,"marks45"))[4]==12000,"untreated wound never vanishes just from time");R.set(w,"bandaged",true);R.set(w,"infected",true);Wounds45.tick(w);ok(((int[])R.get(w,"marks45"))[4]==12000,"infection pauses closure");R.set(w,"infected",false);R.set(w,"dirty",true);Wounds45.tick(w);ok(((int[])R.get(w,"marks45"))[4]==12000,"dirty dressing pauses closure");R.set(w,"dirty",false);R.set(w,"bullets",1);Wounds45.tick(w);ok(((int[])R.get(w,"marks45"))[4]==12000,"unresolved lodged bullet pauses closure");R.set(w,"bullets",0);R.set(w,"healingLeft",2399);Wounds45.tick(w);ok(((int[])R.get(w,"marks45"))[4]==11995,"clean treatment closes wound gradually");R.set(w,"recovered",true);R.set(w,"healingLeft",0);Wounds45.tick(w);ok(((int[])R.get(w,"marks45")).length==0,"fully healed marks return to original skin");
  for(int i=0;i<100;i++)a=Wounds45.add(a,i/100d,.3,0,2);ok(a.length==120,"per-part budget bounded at 24 marks");ok(Wounds45.sanitize(new int[]{-1,0,0,1,4}).length==0,"reject corrupt wound coordinates");ok(Wounds45.sanitize(new int[1000]).length==0,"reject oversized save data");
  var state=new State();for(int i=0;i<8;i++){state.wounds[i]=R.make("ichttt.mods.firstaid.survival.ClinicalState$Wound");R.set(state.wounds[i],"marks45",Wounds45.add(new int[0],i/8d,.3,.1,1));}ichttt.mods.firstaid.survival.ClinicalData.current=state;var root=new CompoundTag();var clinical=new CompoundTag();root.put("zomboidClinical",clinical);for(int i=0;i<8;i++)clinical.put("part"+i,new CompoundTag());Wounds45.write(new Model(),root);for(Object part:state.wounds)R.set(part,"marks45",new int[0]);Wounds45.read(new Model(),root);for(int i=0;i<8;i++)ok(((int[])R.get(state.wounds[i],"marks45"))[0]==Math.round(i/8d*255),"NBT round trip preserves each wound location");
  var player=new ServerPlayer(12);player.model=new Model();var corpse=new CorpseEntity(34);ok(Linked45.skipDeath(player),"native duplicate is suppressed before Corpse creation");Linked45.attach(corpse,player);ok(ServerRagdollSyncManager.RETAINED.size()==1&&ServerRagdollSyncManager.RETAINED.containsKey(34),"one retained body under Corpse entity ID");Object packet=ServerRagdollSyncManager.RETAINED.get(34).spawnPacket;ok(((Number)R.get(packet,"originalEntityId")).intValue()==34,"physics packet uses corpse ID");ok(Linked45.medical(packet).length==56,"all eight clinical wound snapshots reach corpse packet");var saved=new CompoundTag();Linked45.save(corpse,saved);Linked45.removed(corpse);ok(ServerRagdollSyncManager.RETAINED.isEmpty(),"removing corpse removes its physics body");var loaded=new CorpseEntity(99);Linked45.load(loaded,saved);Linked45.tick(loaded);ok(ServerRagdollSyncManager.RETAINED.size()==1&&ServerRagdollSyncManager.RETAINED.containsKey(99),"reloaded corpse uses new entity ID without a duplicate");ok(Linked45.medical(ServerRagdollSyncManager.RETAINED.get(99).spawnPacket).length==56,"medical marks survive corpse save and load");Linked45.tick(loaded);ok(ServerRagdollSyncManager.RETAINED.size()==1,"repeated tick does not register a second body");Linked45.removed(loaded);
  var npc=new mod.cdv.tnpc.entity.AutoGunOperator(101);var npcCorpse=new CorpseEntity(202);mod.cdv.tnpc.tactical.Link31.begin(npc);mod.cdv.tnpc.tactical.Link31.call(new Spawner(),"addFreshEntity",new Object[]{npcCorpse});mod.cdv.tnpc.tactical.Link31.end();ok(ServerRagdollSyncManager.RETAINED.containsKey(202),"NPC corpse attachment is registered only after successful spawn");Object np=ServerRagdollSyncManager.RETAINED.get(202).spawnPacket;ok(R.get(np,"medical45").equals("-101"),"NPC slim model preserved in corpse snapshot");ok(R.get(np,"goreTexture13").equals("tacznpcs:textures/test.png"),"NPC keeps its own texture instead of default zombie skin");Linked45.removed(npcCorpse);
  var carrier=new Packet();carrier.goreCuts24=new int[0];double[]start={0,0,-1},end={0,0,1};ok(Double.isFinite(Ray45.trace(start,end,1,carrier)),"intact head intercepts projectile");carrier.goreCuts24=Cuts24.add(new int[0],new Cuts24.Cut(0,.5,.5,.5,15.9375));ok(!Double.isFinite(Ray45.trace(start,end,1,carrier)),"destroyed head no longer intercepts projectile");
  System.out.println("MEDICAL_POSTURE_PERSISTENCE_HEALING_CORPSE_AND_COLLISION_CHECKS="+count);
 }
}
